import numpy as np

def cashflows(perf, terms):
    perf = np.asarray(perf)
    n_paths, n_dates, n_assets = perf.shape
    notional = float(terms["notional"])
    final_index = int(terms["final_index"])
    downside = terms.get("downside", None)
    upside = terms.get("upside", None)
    autocall = terms.get("autocall", None)
    coupon = terms.get("coupon", None)

    cash = np.zeros((n_paths, n_dates), dtype=float)
    worst = np.min(perf, axis=2)

    active = np.ones(n_paths, dtype=bool)

    has_memory = False
    if coupon is not None and coupon.get("memory", False):
        has_memory = True
        carry = np.zeros(n_paths, dtype=float)
    else:
        carry = None

    for i in range(n_dates):
        w = worst[:, i]
        is_final = (i == final_index)

        if coupon is not None:
            amounts = coupon.get("amounts", [])
            amt = amounts[i] if i < len(amounts) else None
            if amt is not None:
                barrier = coupon["barrier"]
                cond = w >= barrier
                if has_memory:
                    pay_mask = active & cond
                    if np.any(pay_mask):
                        cash[pay_mask, i] += carry[pay_mask] + float(amt)
                        carry[pay_mask] = 0.0
                    accrue_mask = active & (~cond)
                    if np.any(accrue_mask):
                        carry[accrue_mask] += float(amt)
                else:
                    pay_mask = active & cond
                    if np.any(pay_mask):
                        cash[pay_mask, i] += float(amt)

        if autocall is not None:
            call_amounts = autocall.get("call_amounts", [])
            call_amt = call_amounts[i] if i < len(call_amounts) else None
            if call_amt is not None:
                trig = autocall["trigger"]
                cond_call = w >= trig
                call_mask = active & cond_call
                if np.any(call_mask):
                    cash[call_mask, i] += float(call_amt)
                    active[call_mask] = False

        if is_final:
            still = active
            if np.any(still):
                final_w = w
                if downside is not None:
                    level = downside["level"]
                    obs = downside.get("observation", "final_only")
                    if obs == "final_only":
                        breached = final_w < level
                    else:
                        min_worst = np.min(worst[:, :final_index + 1], axis=1)
                        breached = min_worst < level
                else:
                    breached = np.zeros(n_paths, dtype=bool)

                if upside is not None:
                    lev = upside["leverage"]
                    cap = upside.get("cap", None)
                    ups_mask = still & (final_w > 1.0)
                    if np.any(ups_mask):
                        fw_ups = final_w[ups_mask]
                        if cap is None:
                            payoff_ups = notional * (1.0 + lev * (fw_ups - 1.0))
                        else:
                            ret = lev * (fw_ups - 1.0)
                            ret = np.minimum(ret, cap)
                            payoff_ups = notional * (1.0 + ret)
                        cash[ups_mask, i] += payoff_ups
                    remaining = still & (~ups_mask)
                    if np.any(remaining):
                        not_breached = remaining & (~breached)
                        breached_rem = remaining & breached
                        if np.any(not_breached):
                            cash[not_breached, i] += notional
                        if np.any(breached_rem):
                            fw_br = final_w[breached_rem]
                            kind = downside["kind"] if downside is not None else "barrier"
                            gear = float(downside["gearing"]) if downside is not None else 1.0
                            lvl = float(downside["level"]) if downside is not None else 1.0
                            if kind == "barrier":
                                payoff_br = notional * (1.0 - gear * (1.0 - fw_br))
                            elif kind == "buffer":
                                payoff_br = notional * (1.0 - gear * (lvl - fw_br))
                            else:
                                payoff_br = notional * fw_br
                            payoff_br = np.maximum(payoff_br, 0.0)
                            cash[breached_rem, i] += payoff_br
                else:
                    not_breached = still & (~breached)
                    breached_active = still & breached
                    if np.any(not_breached):
                        cash[not_breached, i] += notional
                    if np.any(breached_active):
                        fw_br = final_w[breached_active]
                        kind = downside["kind"] if downside is not None else "barrier"
                        gear = float(downside["gearing"]) if downside is not None else 1.0
                        lvl = float(downside["level"]) if downside is not None else 1.0
                        if kind == "barrier":
                            payoff_br = notional * (1.0 - gear * (1.0 - fw_br))
                        elif kind == "buffer":
                            payoff_br = notional * (1.0 - gear * (lvl - fw_br))
                        else:
                            payoff_br = notional * fw_br
                        payoff_br = np.maximum(payoff_br, 0.0)
                        cash[breached_active, i] += payoff_br
                active[:] = False
    return cash
